    28	    const frame = frames[frames.length - 1];
    29	    const pad = '  '.repeat(frames.length);
    30	    if (frame.next === frame.count) {
    31	      frames.pop();
    32	      pieces.push(`\n${'  '.repeat(frames.length)}${frame.keys ? '}' : ']'}`);
    33	      continue;
